import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"지원 파일 관리자 및 대화상자 연동","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 3대 핵심 연동 기능","slug":"_1-3대-핵심-연동-기능","link":"#_1-3대-핵심-연동-기능","children":[]},{"level":2,"title":"2. 시스템 기본 컴포넌트 지원 (기본 탑재)","slug":"_2-시스템-기본-컴포넌트-지원-기본-탑재","link":"#_2-시스템-기본-컴포넌트-지원-기본-탑재","children":[]},{"level":2,"title":"3. 전문 서드파티 파일 관리자 지원 (선택 플러그인)","slug":"_3-전문-서드파티-파일-관리자-지원-선택-플러그인","link":"#_3-전문-서드파티-파일-관리자-지원-선택-플러그인","children":[{"level":3,"title":"Directory Opus 전용 연동","slug":"directory-opus-전용-연동","link":"#directory-opus-전용-연동","children":[]},{"level":3,"title":"Everything 호환 서비스 (IPC)","slug":"everything-호환-서비스-ipc","link":"#everything-호환-서비스-ipc","children":[]}]},{"level":2,"title":"4. 자체 제작 대화상자 소프트웨어 지원 (전용 플러그인)","slug":"_4-자체-제작-대화상자-소프트웨어-지원-전용-플러그인","link":"#_4-자체-제작-대화상자-소프트웨어-지원-전용-플러그인","children":[]}],"relativePath":"ko-KR/user-guide/file-manager-support.md","filePath":"ko-KR/user-guide/file-manager-support.md","lastUpdated":1791112464000}`),a={name:`ko-KR/user-guide/file-manager-support.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="지원-파일-관리자-및-대화상자-연동" tabindex="-1">지원 파일 관리자 및 대화상자 연동 <a class="header-anchor" href="#지원-파일-관리자-및-대화상자-연동" aria-label="Permalink to “지원 파일 관리자 및 대화상자 연동”">​</a></h1><p>Lertaro는 독립형 실행기로 동작하는 동시에 Windows 파일 탐색기, 서드파티 파일 관리자 및 각종 소프트웨어 대화상자에 내장되어 파일 열기, 저장 및 디렉토리 이동 효율을 높입니다.</p><h2 id="_1-3대-핵심-연동-기능" tabindex="-1">1. 3대 핵심 연동 기능 <a class="header-anchor" href="#_1-3대-핵심-연동-기능" aria-label="Permalink to “1. 3대 핵심 연동 기능”">​</a></h2><p>대상 창의 특성에 따라 최대 세 가지 연동 기능이 제공됩니다.</p><ul><li><strong>인라인 검색 (Inline Search)</strong>: 대상 창 상단이나 파일 대화상자 내부에 검색창이 직접 임베드되어 현재 작업 창을 벗어나지 않고 검색 수행. 지원되는 파일 목록에서 글자나 숫자를 입력하는 순간 나타나며, 그 첫 글자를 자기 상자 안에 담아 가져갑니다.</li><li><strong>퀵 내비게이션 (Quick Navigation)</strong>: 빈 공간을 휠클릭(또는 켜 두었다면 좌클릭 더블클릭, <strong>기본값은 꺼짐</strong>)하거나 임베드된 로고를 클릭하여 열린 폴더, 즐겨찾기, 최근 기록 및 사용자 지정 폴더의 계단식 메뉴 호출. 서드파티 파일 관리자는 휠클릭만 지원합니다.</li><li><strong>활성 경로 감지 (Active Path Detection)</strong>: 대상 창에서 현재 열려 있는 실제 디렉토리를 실시간으로 감지하여 검색 범위를 해당 폴더로 자동 제한하거나 상대 경로 동작 수행.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>파일 대화상자에 도킹된 인라인 카드는 의도적으로 <strong>키보드를 대화상자 쪽에 남겨 둡니다</strong>. 그래서 타이핑은 전과 똑같이 계속 됩니다. <code>Ctrl</code> 더블 클릭(또는 설정해 둔 호출 단축키)으로 캐럿을 카드로 옮기고, 카드가 비어 있는 상태에서 다시 누르면 포커스를 돌려보냅니다. <a href="./hotkeys.html"><strong>단축키</strong></a> 문서의 &quot;인라인 윈도우 호출 및 포커스 인계&quot; 섹션을 참고하세요.</p></div><h2 id="_2-시스템-기본-컴포넌트-지원-기본-탑재" tabindex="-1">2. 시스템 기본 컴포넌트 지원 (기본 탑재) <a class="header-anchor" href="#_2-시스템-기본-컴포넌트-지원-기본-탑재" aria-label="Permalink to “2. 시스템 기본 컴포넌트 지원 (기본 탑재)”">​</a></h2><p>별도의 플러그인 설치 없이 Lertaro 코어 엔진에서 기본 지원합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">대상 창 유형</th><th style="text-align:left;">인라인 검색</th><th style="text-align:left;">퀵 내비게이션 호출 방식</th><th style="text-align:left;">활성 경로 감지</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows 파일 탐색기</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">빈 공간 휠클릭, 또는 켜 두었을 때 좌클릭 더블클릭</td><td style="text-align:left;">지원</td></tr><tr><td style="text-align:left;"><strong>모던 열기/저장 파일 대화상자</strong></td><td style="text-align:left;">지원 (대화상자 내 직접 임베드)</td><td style="text-align:left;">휠클릭 또는 임베드된 로고 좌클릭</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>클래식 열기/저장 파일 대화상자</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 임베드된 로고 좌클릭</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>클래식 폴더 찾아보기 대화상자</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 임베드된 로고 좌클릭</td><td style="text-align:left;">—</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>파일 선택 대화상자의 경우 Lertaro가 창 내부에 직접 내장되어 있어 별도의 외부 경로 감지가 필요하지 않습니다. 퀵 내비게이션에서 항목을 클릭하면 대화상자가 해당 폴더로 안전하게 이동합니다.</p></div><h2 id="_3-전문-서드파티-파일-관리자-지원-선택-플러그인" tabindex="-1">3. 전문 서드파티 파일 관리자 지원 (선택 플러그인) <a class="header-anchor" href="#_3-전문-서드파티-파일-관리자-지원-선택-플러그인" aria-label="Permalink to “3. 전문 서드파티 파일 관리자 지원 (선택 플러그인)”">​</a></h2><p>파워 유저를 위한 인기 파일 관리자 전용 플러그인을 제공합니다. <a href="./settings/plugins.html"><strong>설정 → 플러그인</strong></a>에서 활성화하고 인라인 검색과 퀵 내비게이션을 개별 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">파일 관리자</th><th style="text-align:left;">인라인 검색</th><th style="text-align:left;">퀵 내비게이션 호출 방식</th><th style="text-align:left;">활성 경로 감지</th><th style="text-align:left;">핵심 통신 기술</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Directory Opus</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">파일 목록 영역에서 휠클릭</td><td style="text-align:left;">지원</td><td style="text-align:left;"><code>WM_COPYDATA</code> 공식 원격 제어 API</td></tr><tr><td style="text-align:left;"><strong>Total Commander</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">파일 목록 영역에서 휠클릭</td><td style="text-align:left;">지원</td><td style="text-align:left;"><code>WM_COPYDATA</code> 메시지 프로토콜</td></tr><tr><td style="text-align:left;"><strong>XYplorer</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">파일 목록 영역에서 휠클릭</td><td style="text-align:left;">지원</td><td style="text-align:left;">전용 프로세스 통신</td></tr><tr><td style="text-align:left;"><strong>Files</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">파일 목록 영역에서 휠클릭</td><td style="text-align:left;">지원</td><td style="text-align:left;">Windows UI Automation 프레임워크</td></tr><tr><td style="text-align:left;"><strong>One Commander</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">파일 목록 영역에서 휠클릭</td><td style="text-align:left;">지원</td><td style="text-align:left;">Windows UI Automation 프레임워크</td></tr></tbody></table><h3 id="directory-opus-전용-연동" tabindex="-1">Directory Opus 전용 연동 <a class="header-anchor" href="#directory-opus-전용-연동" aria-label="Permalink to “Directory Opus 전용 연동”">​</a></h3><ul><li><strong>재귀 폴더 크기 열 (Lertaro 크기)</strong>: Directory Opus 플러그인에서 &quot;Lertaro 크기 열 활성화&quot;를 켜면 커스텀 스크립트 열이 설치됩니다. Lertaro의 인메모리 인덱스에서 폴더 크기를 직접 읽어오므로 <strong>디스크 I/O가 전혀 없이</strong> 드라이브 전체 폴더 용량을 즉시 확인할 수 있습니다.</li><li><strong>영구 서식 저장</strong>: Directory Opus 열 선택기에서 &quot;Lertaro 크기&quot;를 추가한 후 <strong>폴더 → 폴더 서식 → 저장 → 모든 폴더에 서식 저장</strong>을 클릭합니다.</li></ul><h3 id="everything-호환-서비스-ipc" tabindex="-1">Everything 호환 서비스 (IPC) <a class="header-anchor" href="#everything-호환-서비스-ipc" aria-label="Permalink to “Everything 호환 서비스 (IPC)”">​</a></h3><p><a href="./settings/general.html#_1-시스템-system"><strong>설정 → 일반 → 시스템</strong></a>에서 <strong>Everything 호환 서비스 (IPC) 활성화</strong>를 켜면 표준 Everything Win32 IPC 인터페이스를 에뮬레이트합니다. Directory Opus, Total Commander, Flow Launcher 등에서 Everything 없이도 Lertaro 인덱스를 직접 활용할 수 있습니다.</p><h2 id="_4-자체-제작-대화상자-소프트웨어-지원-전용-플러그인" tabindex="-1">4. 자체 제작 대화상자 소프트웨어 지원 (전용 플러그인) <a class="header-anchor" href="#_4-자체-제작-대화상자-소프트웨어-지원-전용-플러그인" aria-label="Permalink to “4. 자체 제작 대화상자 소프트웨어 지원 (전용 플러그인)”">​</a></h2><p>표준 Windows 대화상자를 쓰지 않는 주요 소프트웨어를 위한 전용 플러그인을 제공합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">소프트웨어 및 대화상자 유형</th><th style="text-align:left;">인라인 검색</th><th style="text-align:left;">퀵 내비게이션 호출 방식</th><th style="text-align:left;">연동 설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>WPS Office</strong> 열기/저장 대화상자</td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 로고 클릭</td><td style="text-align:left;">WPS Writer, Spreadsheets, Presentation, PDF 지원</td></tr><tr><td style="text-align:left;"><strong>WinRAR</strong> 압축 해제 대화상자</td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 로고 클릭</td><td style="text-align:left;">압축 해제 대상 폴더 빠른 지정</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> 압축 해제 대화상자</td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 로고 클릭</td><td style="text-align:left;">해제 대상 폴더 즉시 선택</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> 파일 추가 대화상자</td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 로고 클릭</td><td style="text-align:left;">압축할 소스 파일 빠른 선택</td></tr><tr><td style="text-align:left;"><strong>AutoCAD</strong> 열기/저장 대화상자</td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 로고 클릭</td><td style="text-align:left;">CAD 도면 파일의 신속한 저장 및 호출에 최적화</td></tr></tbody></table><p>각 플러그인은 컨트롤 계층 구조와 핸들을 직접 감지하여 동작하므로 다국어 언어팩이나 테마 변경에 영향을 받지 않습니다.</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};